changeSet.sql:
ALTER TABLE document_versions ADD CONSTRAINT ck_document_versions_version CHECK (business_version >= 1);
ALTER TABLE document_versions ADD CONSTRAINT ck_document_versions_status CHECK (status IN ('Draft','Submitted','InReview','Approved','Rejected','Published','Archived'));
ALTER TABLE document_version_sections ADD CONSTRAINT ck_document_version_sections_position CHECK (section_position >= 0);
ALTER TABLE document_version_sections ADD CONSTRAINT ck_document_version_sections_content CHECK (length(content) <= 100000);
